					ctx.ReclaimUntrackedRegs()
					d0 = args[0]
					d0.ID = 0
					d1 = ctx.EmitGetTagDesc(&d0, JITValueDesc{Loc: LocAny})
					ctx.FreeDesc(&d0)
					ctx.EnsureDesc(&d1)
